contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 amount, address other) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(other != address(this));
        uint256 beforeSelf;
        try c.balances(address(this)) returns (uint256 __r) { beforeSelf = __r; } catch { return; }
        uint256 beforeOther;
        try c.balances(other) returns (uint256 __r) { beforeOther = __r; } catch { return; }
        try c.Deposit{value: amount}() {} catch { return; }
        uint256 afterSelf;
        try c.balances(address(this)) returns (uint256 __r) { afterSelf = __r; } catch { return; }
        uint256 afterOther;
        try c.balances(other) returns (uint256 __r) { afterOther = __r; } catch { return; }
        assertTrue(afterSelf == beforeSelf + amount && afterOther == beforeOther);
